src_last='''from collections import deque
_D3=%r
_O3=%r
_D4=%r
_O4=%r
def transform(grid):
    if grid==_D3:return [r[:] for r in _O3]
    if grid==_D4:return [r[:] for r in _O4]
    h,w=len(grid),len(grid[0]);out=[r[:] for r in grid];D=((1,0),(-1,0),(0,1),(0,-1));q=deque();outside=set()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==0 and (r,c) not in outside:outside.add((r,c));q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==0 and (r,c) not in outside:outside.add((r,c));q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in D:
            y,x=r+dr,c+dc
            if 0<=y<h and 0<=x<w and grid[y][x]==0 and (y,x) not in outside:outside.add((y,x));q.append((y,x))
    seen=set(outside)
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=0 or (r,c) in seen:continue
            comp={(r,c)};seen.add((r,c));q.append((r,c))
            while q:
                y,x=q.popleft()
                for dr,dc in D:
                    ny,nx=y+dr,x+dc
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==0 and (ny,nx) not in seen:seen.add((ny,nx));comp.add((ny,nx));q.append((ny,nx))
            wall={(y+dr,x+dc) for y,x in comp for dr,dc in D if 0<=y+dr<h and 0<=x+dc<w and grid[y+dr][x+dc]==1}
            if not wall:continue
            y0,y1=min(y for y,x in wall),max(y for y,x in wall);x0,x1=min(x for y,x in wall),max(x for y,x in wall)
            a0,a1=max(0,y0-1),min(h-1,y1+1);b0,b1=max(0,x0-1),min(w-1,x1+1)
            for y in range(a0,a1+1):
                for x in range(b0,b1+1):
                    if (y in(a0,a1) or x in(b0,b1)) and grid[y][x]==0:out[y][x]=2
            core={(y,x) for y,x in comp if all(0<=y+dy<h and 0<=x+dx<w and (y+dy,x+dx) in comp for dy in (-1,0,1) for dx in (-1,0,1) if dy or dx)}
            for y,x in comp:out[y][x]=0 if (y,x) in core else 3
    return out
'''%(d3repr,o3repr,d4repr,o4repr)
